function FindMaxArea(height: array of integer): integer;
begin
  var stack := new Stack<integer>;
  var maxArea := 0;
  var index := 0;
  while index < height.Length do
  begin
    if (stack.Count = 0) or (height[index] >= height[stack.Peek]) then
    begin
      stack.Push(index);
      index += 1;
    end
    else
    begin
      var top := stack.Pop;
      var area := height[top] * (if stack.Count = 0 then index else index - stack.Peek - 1);
      maxArea := Max(maxArea, area);
    end;
  end;
  while stack.Count > 0 do
  begin
    var top := stack.Pop;
    var area := height[top] * (if stack.Count = 0 then index else index - stack.Peek - 1);
    maxArea := Max(maxArea, area);
  end;
  Result := maxArea;
end;

