function FindTownJudge(N: integer; trust: array of (integer, integer)): integer;
begin
  var relationship := new Dictionary<integer, HashSet<integer>>;
  foreach var relation in trust do
  begin
    if not relationship.ContainsKey(relation[0]) then
      relationship[relation[0]] := new HashSet<integer>;
    relationship[relation[0]].Add(relation[1]);
  end;
  var possibleTownJudge: integer := -1;
  for var i := 1 to N do
    if (not relationship.ContainsKey(i)) or (relationship[i].Count = 0) then
      possibleTownJudge := i;
  for var i := 1 to N do
    if possibleTownJudge <> i then
      if (not relationship.ContainsKey(i)) or (not relationship[i].Contains(possibleTownJudge)) then
      begin
        Result := -1;
        exit;
      end;
  Result := possibleTownJudge;
end;

