function MinimumOperationsToPalindrome(s: string): integer;
begin
  var n := s.Length;
  var dp := new integer[n, n];
  for var len := 2 to n do
  begin
    for var i := 0 to n - len do
    begin
      var j := i + len - 1;
      if s[i + 1] = s[j + 1] then
        dp[i, j] := dp[i + 1, j - 1]
      else
        dp[i, j] := Min(dp[i + 1, j], dp[i, j - 1]) + 1;
    end;
  end;
  Result := dp[0, n - 1];
end;

