  begin
    Result := 0;
    exit;
  end;
  var startTimes := meetings.Select(m -> m[0]).Order.ToArray;
  var endTimes := meetings.Select(m -> m[1]).Order.ToArray;
  var maxRooms := 0;
  var currentRooms := 0;
  var i := 0;
  var j := 0;
  while (i < meetings.Length) and (j < meetings.Length) do
  begin
    if startTimes[i] < endTimes[j] then
    begin
      currentRooms += 1;
      i += 1;
    end
    else
    begin
      currentRooms -= 1;
      j += 1;
    end;
    maxRooms := Max(maxRooms, currentRooms);
  end;
  Result := maxRooms;
end;

