function StringTransformation(source, target: string): integer;
begin
  var lenSource := source.Length;
  var lenTarget := target.Length;
  var dp := new integer[lenSource + 1, lenTarget + 1
    ];
  for var i := 0 to lenSource do
    for var j := 0 to lenTarget do
    begin
      if i = 0 then
        dp[i, j
    ] := j
      else if j = 0 then
        dp[i, j
    ] := i
      else if source[i - 1
    ] = target[j - 1
    ] then
        dp[i, j
    ] := dp[i - 1, j - 1
    ]
      else
        dp[i, j
    ] := 1 + Min(Min(dp[i - 1, j
    ], dp[i, j - 1
    ]), dp[i - 1, j - 1
    ]);
    end;
  Result := dp[lenSource, lenTarget
    ];
end;

