  dp[0, 0] := 1;
  for var r := 0 to m - 1 do
    for var c := 0 to n - 1 do
    begin
      if r > 0 then
        dp[r, c] += dp[r - 1, c];
      if c > 0 then
        dp[r, c] += dp[r, c - 1];
    end;
  Result := dp[m - 1, n - 1];
end;

