function CombinationSum3(k, n: integer): List<List<integer>>;

  procedure Dfs(path: List<integer>; start: integer; target: integer; res: List<List<integer>>);
  begin
    if path.Count = k then
    begin
      if target = 0 then
        res.Add(new List<integer>(path));
      exit;
    end;

    for var i := start to 9 do
    begin
      if i > target then break;

      path.Add(i);
      Dfs(path, i + 1, target - i, res);
      path.RemoveAt(path.Count - 1);
    end;
  end;

begin
