function MatchPattern(word, pattern: string): boolean;
begin
  var i := 1;
  var j := 1;
  while (i <= word.Length) and (j <= pattern.Length) do
  begin
    if (pattern[j
    ] = '?') or (pattern[j
    ] = word[i
    ]) then
    begin
      i += 1;
      j += 1;
    end
    else
    begin
      Result := False;
      exit;
    end;
  end;
  if (i = word.Length + 1) and (j = pattern.Length + 1) then
    Result := True
  else if (i = word.Length + 1) and (pattern[j
    ] = '?') then
    Result := MatchPattern(word, pattern[j + 1:
    ])
  else if (j = pattern.Length + 1) and (word[i
    ] = pattern[j - 1
    ]) then
    Result := MatchPattern(word[i + 1:
    ], pattern)
  else
    Result := False;
end;

