  if n <= 1 then
  begin
    Result := False;
    exit;
  end;
  if n <= 3 then
  begin
    Result := True;
    exit;
  end;
  if (n mod 2 = 0) or (n mod 3 = 0) then
  begin
    Result := False;
    exit;
  end;
  var i := 5;
  while i * i <= n do
  begin
    if (n mod i = 0) or (n mod (i + 2) = 0) then
    begin
      Result := False;
      exit;
    end;
    i += 6;
  end;
  Result := True;
end;

