function NumOfLIS(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;
  var length := nums.Length;
  var dpLen := ArrFill(length,1);
  var dpNum := ArrFill(length, 1);
  var maxLen := 1;
  var res := 0;
  for var i := 1 to length - 1 do
  begin
    for var j := 0 to i - 1 do
    begin
      if nums[i
    ] > nums[j
    ] then
      begin
        if dpLen[j
    ] + 1 > dpLen[i
    ] then
        begin
          dpLen[i
    ] := dpLen[j
    ] + 1;
          dpNum[i
    ] := dpNum[j
    ];
        end
        else if dpLen[j
    ] + 1 = dpLen[i
    ] then
          dpNum[i
    ] += dpNum[j
    ];
      end;
    end;
    maxLen := Max(maxLen, dpLen[i
    ]);
  end;
  for var i := 0 to length - 1 do
    if dpLen[i
    ] = maxLen then
      res += dpNum[i
    ];
  Result := res;
end;

