type
  Node = class
    val: integer;
    next: Node;
    constructor(v: integer);
    begin
      val := v;
      next := nil;
    end;
  end;

  MyLinkedList = class
    head: Node;
    size: integer;
    constructor;
    begin
      head := nil;
      size := 0;
    end;

    function Get(index: integer): integer;
    begin
      if (index >= size) or (index < 0) then
      begin
        Result := -1;
        exit;
      end;
      var currNode := head;
      for var k := 1 to index do
        currNode := currNode.next;
      Result := currNode.val;
    end;

    procedure AddAtHead(val: integer);
    begin
      var newNode := new Node(val);
      if head = nil then
        head := newNode
      else
      begin
        newNode.next := head;
        head := newNode;
      end;
      size += 1;
    end;

    procedure AddAtTail(val: integer);
    begin
      var newNode := new Node(val);
      if head = nil then
        head := newNode
      else
      begin
        var currNode := head;
        while currNode.next <> nil do
          currNode := currNode.next;
        currNode.next := newNode;
      end;
      size += 1;
    end;

    procedure AddAtIndex(index: integer; val: integer);
    begin
      if (index < 0) or (index > size) then
        exit;
      var newNode := new Node(val);
      var currNode := head;
      if index = 0 then
      begin
        newNode.next := head;
        head := newNode;
      end
      else
      begin
        for var k := 1 to index - 1 do
          currNode := currNode.next;
        newNode.next := currNode.next;
        currNode.next := newNode;
      end;
      size += 1;
    end;

    procedure DeleteAtIndex(index: integer);
    begin
      if (index < 0) or (size <= index) then
        exit;
      if head = nil then
        exit;
      var currNode := head;
      if index = 0 then
        head := head.next
      else
      begin
        for var k := 1 to index - 1 do
          currNode := currNode.next;
        currNode.next := currNode.next.next;
      end;
      size -= 1;
    end;
  end;

function LinkedListOperations(initialList: array of integer; command: string; params args: array of integer): integer;
begin
  var listOperations := new MyLinkedList;
  foreach var num in initialList do
    listOperations.AddAtTail(num);
  case command of
    'addAtHead': listOperations.AddAtHead(args[
      0
    ]);
    'addAtTail': listOperations.AddAtTail(args[
      0
    ]);
    'addAtIndex': listOperations.AddAtIndex(args[
      0
    ], args[
      1
    ]);
    'get': Result := listOperations.Get(args[
      0
    ]);
    'deleteAtIndex': listOperations.DeleteAtIndex(args[
      0
    ]);
