function NumInversions(lst: array of integer): integer;

  function MergeCount(arr: array of integer; left, right: integer): integer;
  begin
    if left >= right then
    begin
      Result := 0;
      exit;
    end;
    var mid := (left + right) div 2;
    var invCount := MergeCount(arr, left, mid) + MergeCount(arr, mid + 1, right);

    var temp := new integer[right - left + 1];
    var i := left;
    var j := mid + 1;
    var k := 0;

    while (i <= mid) and (j <= right) do
    begin
      if arr[i] <= arr[j] then
      begin
        temp[k] := arr[i];
        i += 1;
      end
      else
      begin
        temp[k] := arr[j];
        j += 1;
        invCount += mid - i + 1;
      end;
      k += 1;
    end;

    while i <= mid do
    begin
      temp[k] := arr[i];
      i += 1;
      k += 1;
    end;

    while j <= right do
    begin
      temp[k] := arr[j];
      j += 1;
      k += 1;
    end;

    for var idx := 0 to temp.Length - 1 do
      arr[left + idx] := temp[idx];

    Result := invCount;
  end;

begin
  var arrCopy := Copy(lst);
  Result := MergeCount(arrCopy, 0, lst.Length - 1);
end;

function FindMinIntervals(intervals: array of (integer, integer)): integer;
