  intervals := intervals.OrderBy(i -> (i[
      0
    ], -i[
      1
    ])).ToArray;
  var coveredPoints := new HashSet<integer>;
  var minIntervals := 0;
  foreach var (start, endVal) in intervals do
  begin
    if not coveredPoints.Any(point -> (point >= start) and (point <= endVal)) then
    begin
      minIntervals += 1;
      for var point := start to endVal do
        coveredPoints.Add(point);
    end;
  end;
  Result := minIntervals;
end;

function DistinctIslands(grid: array [,] of integer): integer;

  function Dfs(i, j: integer; var grid: array [,] of integer; base: string): string;
  begin
    if (i < 0) or (j < 0) or (i >= grid.GetLength(0)) or (j >= grid.GetLength(1)) or (grid[i, j
    ] <> 1) then
    begin
      Result := '';
      exit;
    end;
    grid[i, j
    ] := 0;
    Result := base + '(' + Dfs(i + 1, j, grid, 'd') + Dfs(i - 1, j, grid, 'u') + Dfs(i, j + 1, grid, 'r') + Dfs(i, j - 1, grid, 'l') + ')';
  end;

begin
  var islands := new HashSet<string>;
  for var i := 0 to grid.GetLength(0) - 1 do
    for var j := 0 to grid.GetLength(1) - 1 do
      if grid[i, j
    ] = 1 then
        islands.Add(Dfs(i, j, grid, ''));
  Result := islands.Count;
end;

type
