function MaxPathSum(nums: array of integer): integer;

  function CreateTree(var root: TreeNode; nums: array of integer; i: integer): TreeNode;
  begin
    if i < nums.Length then
    begin
      if nums[i
    ] = 0 then
        Result := nil
      else
      begin
        root := new TreeNode(nums[i
    ]);
        root.left := CreateTree(root.left, nums,2 * i + 1);
        root.right := CreateTree(root.right, nums,2 * i + 2);
        Result := root;
      end;
    end
    else
      Result := nil;
  end;

  function MaxGain(node: TreeNode; var maxSum: integer): integer;
  begin
    if node = nil then
    begin
      Result := 0;
      exit;
    end;
    var leftGain := Max(MaxGain(node.left, maxSum),0);
    var rightGain := Max(MaxGain(node.right, maxSum),0);
    var priceNewpath := node.val + leftGain + rightGain;
    maxSum := Max(maxSum, priceNewpath);
    Result := node.val + Max(leftGain, rightGain);
  end;

begin
  var root: TreeNode := nil;
  root := CreateTree(root, nums,0);
  var maxSum := integer.MinValue;
  MaxGain(root, maxSum);
  Result := maxSum;
end;

function LongestValidParentheses(s: string): integer;
