function ShortestPath(edges: array of (integer, integer); source, target: integer): array of integer;
begin
  var graph := new Dictionary<integer, List<integer>>;
  foreach var edge in edges do
  begin
    if not graph.ContainsKey(edge[
      0
    ]) then
      graph[edge[
        0
      ]
    ] := new List<integer>;
    graph[edge[
        0
      ]
    ].Add(edge[
      1
    ]);
  end;
  var queue := new Queue<integer>;
  queue.Enqueue(source);
  var path := new Dictionary<integer, array of integer>;
  path[source
    ] := Arr(source);
  while queue.Count > 0 do
  begin
    var current := queue.Dequeue;
    if current = target then
      break;
    if graph.ContainsKey(current) then
      foreach var neighbor in graph[current
    ] do
        if not path.ContainsKey(neighbor) then
        begin
          queue.Enqueue(neighbor);
          path[neighbor
    ] := path[current
    ] + Arr(neighbor);
        end;
  end;
  if path.ContainsKey(target) then
    Result := path[target
    ]
  else
    Result := nil;
end;

