function FrogJump(A: array of integer): integer;
begin
  var n := A.Length;
  var jumps := 0;
  var currReach := 0;
  var farthest := 0;
  for var i := 0 to n - 2 do
  begin
    farthest := Max(farthest, i + A[i
    ]);
    if i = currReach then
    begin
      jumps += 1;
      currReach := farthest;
    end;
    if currReach >= n - 1 then
    begin
      Result := jumps;
      exit;
    end;
  end;
  if currReach < n - 1 then
    Result := -1
  else
    Result := jumps;
end;

function SearchElementRange(nums: array of integer; target: integer): (integer, integer);
begin
  if nums.Length = 0 then
  begin
    Result := (-1,-1);
    exit;
  end;
  var lo := 0;
  var hi := nums.Length - 1;
  var center := -1;
  while lo <= hi do
  begin
    var mid := (lo + hi) div 2;
    if nums[mid
] = target then
    begin
      center := mid;
      break;
    end
    else if nums[mid
] > target then
      hi := mid - 1
    else
      lo := mid + 1;
  end;
  if center = -1 then
  begin
    Result := (-1,-1);
    exit;
  end;
  lo := center;
  hi := center;
  while (lo - 1 >= 0) and (nums[lo - 1
] = target) do
    lo -= 1;
  while (hi + 1 <= nums.Length - 1) and (nums[hi + 1
] = target) do
    hi += 1;
  Result := (lo, hi);
end;

