function GridPath(grid: array [,] of integer): integer;
begin
  var m := grid.GetLength(0);
  var n := grid.GetLength(1);
  var dp := new integer[m, n];

  if grid[0, 0] = 0 then
    dp[0, 0] := 1
  else
    dp[0, 0] := 0;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      if grid[i, j] = 1 then
        dp[i, j] := 0
      else
      begin
        if i > 0 then
          dp[i, j] += dp[i - 1, j];
        if j > 0 then
          dp[i, j] += dp[i, j - 1];
      end;
    end;
  Result := dp[m - 1, n - 1];
end;

function SmallestPalindrome(s: string; k: integer): string;

  function ExpandAroundCenter(left, right: integer): string;
  begin
    while (left >= 1) and (right <= s.Length) and (s[left
    ] = s[right
    ]) do
    begin
      left -= 1;
      right += 1;
    end;
    Result := s.Substring(left + 1, right - left - 1);
  end;

begin
  var smallest: string := nil;
  for var i := 1 to s.Length do
  begin
    var palindrome1 := ExpandAroundCenter(i, i);
    var palindrome2 := ExpandAroundCenter(i, i + 1);
    if (palindrome1.Length >= k) and ((smallest = nil) or (palindrome1.Length < smallest.Length)) then
      smallest := palindrome1;
    if (palindrome2.Length >= k) and ((smallest = nil) or (palindrome2.Length < smallest.Length)) then
