function ShiftSentence(sentence: string; n: integer): string;
begin
  var answer := new List<char>;
  for var i := 1 to sentence.Length do
  begin
    var alpha := Ord(sentence[i
    ]);
    var letter := alpha + n;
    if (65 <= alpha) and (alpha <= 90) then
    begin
      if letter > 90 then
        letter := 64 + (letter - 90);
      answer.Add(Chr(letter));
    end
    else if (97 <= alpha) and (alpha <= 122) then
    begin
      if letter > 122 then
        letter := 96 + (letter - 122);
      answer.Add(Chr(letter));
    end
    else
      answer.Add(sentence[i
    ]);
  end;
  Result := answer.JoinToString('');
end;

function ShortestDistance(mat: array [,] of integer): array [,] of integer;
begin
  var queue := new Queue<(integer, integer, integer)>;
  var seen := new HashSet<(integer, integer)>;
  for var i := 0 to mat.GetLength(0) - 1 do
    for var j := 0 to mat.GetLength(1) - 1 do
      if mat[i, j
    ] = 0 then
      begin
        queue.Enqueue((i, j,0));
        seen.Add((i, j));
      end;
  while queue.Count > 0 do
  begin
    var (i, j, steps) := queue.Dequeue;
    var directions := Arr((0,1), (1,0), (-1,0), (0,-1));
    foreach var (di, dj) in directions do
    begin
      var p := i + di;
      var q := j + dj;
      if (0 <= p) and (p < mat.GetLength(0)) and (0 <= q) and (q < mat.GetLength(1)) and not seen.Contains((p, q)) then
      begin
        seen.Add((p, q));
        queue.Enqueue((p, q, steps + 1));
        mat[p, q
] := steps + 1;
      end;
    end;
  end;
  Result := mat;
end;

