  var resultList := new List<integer>;
  var deque := new Queue<integer>;
  for var i := 0 to arr.Length - 1 do
  begin
    while (deque.Count > 0) and (deque.Peek <= i - k) do
      deque.Dequeue;
    while (deque.Count > 0) and (arr[deque.Peek] <= arr[i]) do
      deque.Dequeue;
