function BuildGraph(cells: array of string): Dictionary<string, List<string>>;
begin
  var graph := new Dictionary<string, List<string>>;

  foreach var cell in cells do
  begin
    var s := cell.Replace(' ', '');
    var pos := s.IndexOf('=');

    if pos > 0 then
    begin
      var name := s.Substring(0, pos);
      var expr := s.Substring(pos + 1);

      var deps := new List<string>;
      var cur := '';

      foreach var ch in expr do
      begin
        if ch.IsLetter or ch.IsDigit then
          cur += ch
        else
        begin
          if (cur <> '') and (cur.Any(c -> c.IsDigit)) then
            deps.Add(cur);
          cur := '';
        end;
      end;

      if (cur <> '') and (cur.Any(c -> c.IsDigit)) then
        deps.Add(cur);

      graph[name] := deps;
    end;
  end;

  Result := graph;
end;


function DfsCheck(node: string; graph: Dictionary<string, List<string>>;
                  visited, rec: HashSet<string>): boolean;
begin
  if rec.Contains(node) then
  begin
    Result := True;
    exit;
  end;

  if visited.Contains(node) then
  begin
    Result := False;
    exit;
  end;

  visited.Add(node);
  rec.Add(node);

  if graph.ContainsKey(node) then
    foreach var nb in graph[node] do
      if DfsCheck(nb, graph, visited, rec) then
      begin
        Result := True;
        exit;
      end;

  rec.Remove(node);
  Result := False;
end;


function HasCycle(graph: Dictionary<string, List<string>>): boolean;
begin
  var visited := new HashSet<string>;
  var rec := new HashSet<string>;

  foreach var k in graph.Keys do
    if DfsCheck(k, graph, visited, rec) then
    begin
      Result := True;
      exit;
    end;

  Result := False;
end;


