  var minVal := arr[
      0
    ];
  var maxVal := arr[
      0
    ];
  var start := 0;
  for var endIndex := 0 to arr.Length - 1 do
  begin
    minVal := Min(minVal, arr[endIndex
    ]);
    maxVal := Max(maxVal, arr[endIndex
    ]);
    while maxVal - minVal > threshold do
    begin
      if arr[start
    ] = minVal then
        minVal := arr[start + 1:endIndex + 1
    ].Min
      else if arr[start
    ] = maxVal then
        maxVal := arr[start + 1:endIndex + 1
