function ValidPath(n: integer; edges: array of (integer, integer); source, destination: integer): boolean;
begin
  var g := new Dictionary<integer, List<integer>>;

  foreach var e in edges do
  begin
    var a := e.Item1;
    var b := e.Item2;
    if not g.ContainsKey(a) then g[a] := new List<integer>;
    if not g.ContainsKey(b) then g[b] := new List<integer>;
    g[a].Add(b);
    g[b].Add(a);
  end;

  var visited := new HashSet<integer>;
  var stack := new Stack<integer>;
  stack.Push(source);

  while stack.Count > 0 do
  begin
    var v := stack.Pop;
    if v = destination then
    begin
      Result := True;
      exit;
    end;
    if visited.Contains(v) then continue;
    visited.Add(v);
    if g.ContainsKey(v) then
      foreach var nx in g[v] do
        if not visited.Contains(nx) then
          stack.Push(nx);
  end;

  Result := False;
end;

