  begin
    if a mod 2 = 1 then
      rem := (rem * x) mod p;
    x := (x * x) mod p;
    a := a div 2;
  end;
  case b of
    0: Result := (rem * 3) mod p;
    1: Result := (rem * 4) mod p;
    2: Result := (rem * 6) mod p;
  end;
end;

function FarthestPoint(points: array of array of integer): array of integer;
begin
  var maxDistance := 0.0;
  var farthest := points[
      0
    ];
  foreach var point in points do
  begin
    var distance := Sqrt(point[
      0
    ] ** 2 + point[
      1
    ] ** 2 + point[
      2
    ] ** 2);
    if distance > maxDistance then
    begin
      maxDistance := distance;
      farthest := point;
    end;
  end;
  Result := farthest;
end;

