function FindLongestConsecutiveSequence(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;
  var numsSet := new HashSet<integer>(nums);
  var longest := 0;
  foreach var num in numsSet do
  begin
    if not numsSet.Contains(num - 1) then
    begin
      var currentNum := num;
      var currentStreak := 1;
      while numsSet.Contains(currentNum + 1) do
      begin
        currentNum += 1;
        currentStreak += 1;
      end;
      longest := Max(longest, currentStreak);
    end;
  end;
  Result := longest;
end;

function SumOfNthPowers(n: integer): integer;
begin
  var totalSum := 0;
  var upperBound := n * Round(Power(9, n));
  for var num := 2 to upperBound do
  begin
    var sumOfPowers := 0;
    var temp := num;
    while temp > 0 do
    begin
      var digit := temp mod 10;
      sumOfPowers += Round(Power(digit, n));
      temp := temp div 10;
    end;
    if sumOfPowers = num then
      totalSum += num;
  end;
  Result := totalSum;
end;

function FindTwoMax(arr: array of integer): (integer, integer);
