function GeneratePrimes(n: integer): array of integer;
begin
  var primes := new List<integer>;
  for var num := 2 to n do
  begin
    var isPrime := True;
    for var i := 2 to Round(Sqrt(num)) do
      if num mod i = 0 then
      begin
        isPrime := False;
        break;
      end;
    if isPrime then
      primes.Add(num);
  end;
  Result := primes.ToArray;
end;

function FindClosestPoints(points: array of (real, real)): real;
begin
  if points.Length < 2 then
  begin
    Result := 0;
    exit;
  end;

  var minD := real.MaxValue;

  for var i := 0 to points.Length - 1 do
    for var j := i + 1 to points.Length - 1 do
    begin
      var dx := points[j].Item1 - points[i].Item1;
      var dy := points[j].Item2 - points[i].Item2;
      var d := Sqrt(dx*dx + dy*dy);
      if d < minD then minD := d;
    end;

  Result := minD;
end;

