function MaxWindow(nums: array of integer; k: integer): array of integer;
begin
  if (nums.Length = 0) or (k <= 0) then
  begin
    Result := nil;
    exit;
  end;
  var resultList := new List<integer>;
  var deque := new Queue<integer>;
  for var i := 0 to nums.Length - 1 do
  begin
    while (deque.Count > 0) and (deque.Peek <= i - k) do
      deque.Dequeue;
    while (deque.Count > 0) and (nums[deque.Peek] <= nums[i]) do
      deque.Dequeue;
    deque.Enqueue(i);
    if i >= k - 1 then
      resultList.Add(nums[deque.Peek]);
  end;
  Result := resultList.ToArray;
end;

function EvenNumbersSorted(numbers: array of integer): array of integer;
