function NumberOfSubarrays(nums: array of integer; k: integer): integer;
begin
  var count := new Dictionary<integer, integer>;
  count[0] := 1;
  var odd := 0;
  var res := 0;

  foreach var x in nums do
  begin
    odd += x mod 2;
    if count.ContainsKey(odd - k) then
      res += count[odd - k];
    if count.ContainsKey(odd) then
      count[odd] := count[odd] + 1
    else
      count[odd] := 1;
  end;

  Result := res;
end;

