function RangeList(start, endVal: integer; step: integer := 1): array of integer;
begin
  if step = 0 then
    raise new Exception('Step cannot be zero.');
  var resultList := new List<integer>;
  var current := start;
  if step > 0 then
  begin
    while current <= endVal do
    begin
      resultList.Add(current);
      current += step;
    end;
  end
  else
  begin
    while current >= endVal do
    begin
      resultList.Add(current);
      current += step;
    end;
  end;
  Result := resultList.ToArray;
end;

