function OperationsRequired(str1, str2: string): integer;
begin
  var m := str1.Length;
  var n := str2.Length;
  var dp := new integer[m + 1, n + 1
    ];
  for var i := 0 to m do
    for var j := 0 to n do
    begin
      if i = 0 then
        dp[i, j
    ] := j
      else if j = 0 then
        dp[i, j
    ] := i
      else if str1[i
    ] = str2[j
    ] then
        dp[i, j
    ] := dp[i - 1, j - 1
    ]
      else
        dp[i, j
    ] := 1 + Min(Min(dp[i - 1, j
    ], dp[i, j - 1
    ]), dp[i - 1, j - 1
    ]);
    end;
  Result := dp[m, n
    ];
end;

type
  BinaryNode = class
    val: integer;
    left, right: BinaryNode;
    constructor Create(v: integer);
    begin
      val := v;
    end;
  end;

function PrintFromTopToBottom(root: BinaryNode): array of integer;
begin
  if root = nil then
  begin
    Result := new integer[0];
    exit;
  end;

  var q := new Queue<BinaryNode>;
  var resultList := new List<integer>;

  q.Enqueue(root);

  while q.Count > 0 do
  begin
    var cur := q.Dequeue;
    resultList.Add(cur.val);

    if cur.left <> nil then q.Enqueue(cur.left);
    if cur.right <> nil then q.Enqueue(cur.right);
  end;

  Result := resultList.ToArray;
end;

function CaesarCipherEncode(message: string; shift: integer): string;
begin
  var encodedMessage := '';
  foreach var c in message do
  begin
    if c.IsLetter then
    begin
      var asciiOffset := c.IsUpper ? 65 : 97;
      encodedMessage += Chr((Ord(c) - asciiOffset + shift) mod 26 + asciiOffset);
    end
    else
      encodedMessage += c;
  end;
  Result := encodedMessage;
end;

