end;

function MinPerfectSquares(n: integer): integer;
begin
  var dp := ArrFill(n + 1, integer.MaxValue);
  dp[
      0
    ] := 0;
  for var i := 1 to n do
  begin
    var j := 1;
    while j * j <= i do
    begin
      dp[i
    ] := Min(dp[i
    ], dp[i - j * j
    ] + 1);
      j += 1;
    end;
  end;
  Result := dp[n
    ];
end;

function FindTwoSmallest(numbers: array of integer): (integer, integer);
