function MaxValidParentheses(s: string): integer;
begin
  var maxLen := 0;
  var stack := new Stack<integer>;
  stack.Push(-1);
  for var i := 1 to s.Length do
  begin
    if s[i
    ] = '(' then
      stack.Push(i - 1)
    else
    begin
      stack.Pop;
      if stack.Count = 0 then
        stack.Push(i - 1)
      else
        maxLen := Max(maxLen, i - 1 - stack.Peek);
    end;
  end;
  Result := maxLen;
end;

