function FindKthSmallestPrime(arr: array of integer; k: integer): integer;
begin
  var primes := new List<integer>;
  var primeCount := new Dictionary<integer, integer>;
  var isPrime := ArrFill(arr.Max + 1, True);
  isPrime[
      0
    ] := False;
  isPrime[
      1
    ] := False;
  for var i := 2 to isPrime.Length - 1 do
  begin
    if isPrime[i
    ] then
    begin
      primes.Add(i);
      for var j := i * i to isPrime.Length - 1 step i do
        isPrime[j
    ] := False;
    end;
  end;
  foreach var num in arr do
    if isPrime[num
    ] then
    begin
      if primeCount.ContainsKey(num) then
        primeCount[num
    ] += 1
      else
        primeCount[num
    ] := 1;
    end;
  var primesInArray := primeCount.Keys.Order.ToArray;
  Result := primesInArray[k - 1
    ];
end;

