function MinCostPath(cost: array [,] of integer): integer;
begin
  var m := cost.GetLength(0);
  var n := cost.GetLength(1);
  for var r := 0 to m - 1 do
    for var c := 0 to n - 1 do
    begin
      if (r > 0) and (c > 0) then
        cost[r, c
    ] += Min(cost[r - 1, c
    ], cost[r, c - 1
    ])
      else if r > 0 then
        cost[r, c
    ] += cost[r - 1, c
    ]
      else if c > 0 then
        cost[r, c
    ] += cost[r, c - 1
    ];
    end;
  Result := cost[m - 1, n - 1
    ];
end;

function MinimumOperations(nums: array of integer; start, goal: integer): integer;
begin
  var q := new Queue<(integer, integer)>;
  q.Enqueue((start,0));
  var seen := new HashSet<integer>;
  while q.Count > 0 do
  begin
    var (n, steps) := q.Dequeue;
    if n = goal then
    begin
      Result := steps;
      exit;
    end;
    if (n < 0) or (n > 1000) then
      continue;
    if n in seen then
      continue;
    seen.Add(n);
    foreach var cand in nums do
    begin
      var x := n + cand;
      var y := n - cand;
      var z := n xor cand;
      q.Enqueue((x, steps + 1));
      q.Enqueue((y, steps + 1));
      q.Enqueue((z, steps + 1));
    end;
  end;
  Result := -1;
end;

function CanJumpOnePass(nums: array of integer): boolean;
begin
  var goal := nums.Length - 1;
  var i := nums.Length - 2;
  while i >= 0 do
  begin
    var stepsNeeded := goal - i;
    if nums[i
    ] >= stepsNeeded then
      goal := i;
    i -= 1;
  end;
  Result := goal = 0;
end;

